u5316\u6743\u91cd**\uff1b\u6fc0\u6d3b/KV \u4fdd\u6301 FP16 \u4e0d\u91cf\u5316\u3002\n- **\u4fdd\u771f\u5ea6\u539f\u5219\uff08\u8bbe\u8ba1\u89c4\u8303\uff09**\uff1a\u4ee5\u5b98\u65b9\u4ed3\u5e93\u4e3a\u84dd\u672c\u9010\u5c42\u5bf9\u7167\uff1b\u504f\u79bb\u9ed8\u8ba4\u5b9e\u73b0\u4e4b\u5904\uff08\u5982\u4e0b\u6e38\u4efb\u52a1\u8bc4\u6d4b\u5668\uff09\u9010\u6761\u8bb0\u5f55\u5728\u5b9e\u9a8c\u65e5\u5fd7\u3002\n\n## 4. \u8bc4\u4f30\u534f\u8bae\n- **\u56f0\u60d1\u5ea6\uff08\u4e3b\uff09**\uff1aWikiText-2 \u9a8c\u8bc1\u96c6 PPL\uff08\u8bed\u8a00\u5efa\u6a21\uff0cstride/seq \u5904\u7406\u5bf9\u9f50 GPTQ/QuaRot \u8bba\u6587\u7ea6\u5b9a\u3010\u5047\u8bbe\uff1aseq len 2048\u3001stride 512\u3011\uff1b\u8f85\u4ee5 C4-en \u9a8c\u8bc1\u96c6 PPL\u3010\u5047\u8bbe\uff1a\u56fa\u5b9a\u53ef\u590d\u73b0\u5b50\u96c6/\u56fa\u5b9a seed \u91c7\u6837\u3011\uff09\u3002PPL \u4f4e\u8005\u4f18\u3002\n- **\u4e0b\u6e38\u4efb\u52a1\u51c6\u786e\u7387**\uff1alm-evaluation-harness \u516d\u9879\uff1awinogrande\uff08acc\uff09\u3001arc_easy\uff08acc_norm\uff09\u3001arc_challenge\uff08acc_norm\uff09\u3001hellaswag\uff08acc_norm\uff09\u3001piqa\uff08acc\uff09\u3001boolq\uff08acc\uff09\uff1b\u7edf\u4e00\u4f7f\u7528\u540c\u4e00\u8bc4\u6d4b\u5668\u4e0e seed \u4fdd\u8bc1\u516c\u5e73\u3002\n- **\u8d44\u6e90\u7c7b\u6307\u6807**\uff1a\u5cf0\u503c\u663e\u5b58\uff08MB/GB\uff0c\u63a8\u7406\u8fc7\u7a0b GPU \u5cf0\u503c\uff09\u3001\u541e\u5410\uff08tokens/s\uff09\u4e0e\u5355\u5e8f\u5217\u5ef6\u8fdf\u3001\u91cf\u5316\u540e\u6743\u91cd\u4f53\u79ef\u4e0e\u76f8\u5bf9 FP16 \u538b\u7f29\u6bd4\uff084\u22484\u00d7\u30013\u22485.33\u00d7\u30012\u22488\u00d7\uff0c\u7406\u8bba\u503c\uff09\u3002\n- **\u4e0a\u754c\u6821\u9a8c\uff08\u91cd\u8981\uff09**\uff1aFP16 \u5168\u7cbe\u5ea6\uff08\u65e0\u65cb\u8f6c\uff09\u4e0e FP16 \u5168\u7cbe\u5ea6\uff08\u65cb\u8f6c\u3001\u65e0\u91cf\u5316\uff09\u4e24\u8005 PPL \u5e94\u4e00\u81f4\uff08\u5bb9\u5dee\u5185\uff09\u2014\u2014\u7528\u4e8e**\u9a8c\u8bc1\"\u8ba1\u7b97\u4fdd\u6301\u65cb\u8f6c\"\u786e\u5b9e\u51fd\u6570\u7b49\u4ef7**\uff0c\u662f QuaRot \u5b9e\u73b0\u6b63\u786e\u6027\u7684\u5fc5\u8981 sanity check\u3002\n\n## 5. \u7edf\u8ba1\u4e0e\u5206\u6790\u8ba1\u5212\n- **\u91cd\u590d\u4e0e\u6c47\u603b**\uff1a\u6bcf\u683c 3 seeds\u3010\u5047\u8bbe\u3011\uff08GPTQ \u6821\u51c6\u5b50\u91c7\u6837 seed \u00d7 QuaRot \u968f\u673a\u7b26\u53f7/H seed \u7ec4\u5408\u91c7\u6837\uff09\uff0c\u62a5\u544a mean\u00b1std\u3002\n- **\u4e3b\u5206\u6790\uff08\u0394 \u6307\u6807\u91cf\u5316\u65cb\u8f6c\u5355\u72ec\u8d21\u732e\uff09**\uff1a\u5bf9\u6bcf\u4e2a (\u6a21\u578b, \u91cf\u5316\u5668, \u4f4d\u5bbd) \u683c\uff0c\u0394PPL = PPL(\u65e0\u65cb\u8f6c) \u2212 PPL(\u65cb\u8f6c)\uff08>0 \u8868\u793a\u65cb\u8f6c\u964d PPL\uff09\u3001\u0394Acc = Acc(\u65cb\u8f6c) \u2212 Acc(\u65e0\u65cb\u8f6c)\uff08>0 \u8868\u793a\u65cb\u8f6c\u63d0\u5347\u51c6\u786e\u7387\uff09\u3002\u7528\u914d\u5bf9 t \u68c0\u9a8c\u6216 Wilcoxon\uff08\u8de8\u6a21\u578b\u00d7\u4f4d\u5bbd\u683c\u914d\u5bf9\uff09\uff0c\u62a5\u544a\u6548\u5e94\u91cf\u4e0e p \u503c\u3010\u5047\u8bbe\uff1a\u663e\u8457\u6027\u9608\u503c \u03b1=0.05\u3011\uff1b\u540c\u65f6\u62a5\u544a\u5404\u683c\u76f8\u5bf9 FP16 \u7684\u9000\u5316\u91cf\u3002\n- **H3 \u68c0\u9a8c**\uff1a\u6309\u4f4d\u5bbd\u5206\u5c42\u7ed8\u5236 \u0394 \u6307\u6807\u8d8b\u52bf\uff084\u21923\u21922\uff09\uff0c\u9a8c\u8bc1\"\u65cb\u8f6c\u6536\u76ca\u968f\u4f4d\u5bbd\u4e0b\u964d\u589e\u5927\"\u3002\n- **\u7a33\u5065\u6027\u626b\u63cf**\uff1ag\u2208{64,256} \u91cd\u590d\u4e0a\u8ff0\u4e3b\u5206\u6790\uff0c\u786e\u8ba4\u7ed3\u8bba\u5bf9\u5206\u7ec4\u4e0d\u654f\u611f\uff1b\u5bf9 GPTQ \u505a desc_act\u2208{True,False} \u7684\u5c0f\u578b\u654f\u611f\u6027\u68c0\u67e5\uff08TinyLlama+7B\uff0c4/3 bit\uff0c\u65cb\u8f6c\u00b1\uff09\u68c0\u9a8c H2\u3002\n\n## 6. \u5bf9\u7167\u4e0e\u6d88\u878d\n- **C0 \u4e0a\u754c\u5bf9\u7167**\uff1aFP16 \u65e0\u65cb\u8f6c vs FP16 \u65cb\u8f6c\uff08\u51fd\u6570\u7b49\u4ef7\u6821\u9a8c\uff09\u3002\n- **C1 \u4e3b\u5bf9\u7167\uff08\u914d\u5bf9\uff09**\uff1a\u65e0\u65cb\u8f6c RTN/GPTQ\uff08\u5bf9\u7167\uff09= vs \u65cb\u8f6c RTN/GPTQ\uff08\u5904\u7406\uff09\uff0c\u9694\u79bb\u65cb\u8f6c\u5355\u72ec\u8d21\u732e\u3002\n- **A1 \u975e\u4fdd\u6301\u8bca\u65ad\uff08\u987b\u6807\u6ce8\uff09**\uff1a\u4ec5\u65cb\u8f6c\u6743\u91cd\u3001\u4e0d\u65cb\u8f6c\u6fc0\u6d3b/\u5d4c\u5165\u2014\u2014**\u975e\u51fd\u6570\u4fdd\u6301\u3001\u4ec5\u5185\u90e8\u8bca\u65ad**\uff0c\u4e0d\u5f97\u89e3\u91ca\u4e3a\u6700\u7ec8\u6a21\u578b\u884c\u4e3a\uff1b\u7528\u4e8e\u5f52\u56e0\u6536\u76ca\u6765\u81ea\u6743\u91cd\u4fa7\u8fd8\u662f\u6fc0\u6d3b\u4fa7\u3002\n- **A2 KV \u65cb\u8f6c\u5f00\u5173\u654f\u611f\u6027**\uff1a\u5728\"\u4ec5\u6743\u91cd\u91cf\u5316\"\u4e0b\u628a QuaRot \u7684 Q/K/KV \u65cb\u8f6c\u5f00\u5173\u6253\u5f00/\u5173\u95ed\uff0c\u8bc4\u4f30\u5bf9\u6743\u91cd\u4ec5\u91cf\u5316\u7ed3\u679c\u7684\u654f\u611f\u5ea6\uff08\u9884\u671f\u5f71\u54cd\u5f88\u5c0f\uff0c\u9a8c\u8bc1\u56fe\u7ea7\u65cb\u8f6c\u5e03\u7f6e\u662f\u5426\u9700\u8981\uff09\u3002\n- **A3\uff08\u53ef\u9009\uff09\u65cb\u8f6c\u5b9e\u73b0\u7a33\u5065\u6027**\uff1a\u5168\u7ef4 vs \u5206\u5757 Hadamard\u3001\u6709\u65e0 online LN\uff0c\u68c0\u67e5\u6570\u503c\u4e00\u81f4\u6027\u4e0e\u7a33\u5b9a\u6027\u3002\n- **A4\uff08\u53ef\u9009\uff09**\uff1a\u975e\u5bf9\u79f0 vs \u5bf9\u79f0\u91cf\u5316\u5bf9 2 bit \u7ed3\u679c\u7684\u5f71\u54cd\u3002\n\n## 7. \u53ef\u884c\u6027\u3001\u98ce\u9669\u4e0e\u66ff\u4ee3\u65b9\u6848\n- **\u7b97\u529b\u524d\u63d0\u3010\u5047\u8bbe\u3011**\uff1a\u4e3b\u77e9\u9635\uff087B/13B \u7aef\u5230\u7aef\uff09\u9700 \u22651\u00d7A100(80G) \u6216 H100\uff0813B FP16 \u6743\u91cd\u224826GB\uff0c\u52a0\u6fc0\u6d3b\u4e0e\u8bc4\u6d4b\u5668\u9700 80GB \u7ea7\uff09\uff1b\u65e0\u6b64\u8d44\u6e90\u5219**\u4ec5\u5c0f\u6a21\u578b\uff08TinyLlama/OPT/GPT-2\uff09+ PPL** \u90e8\u5206\u53ef\u6267\u884c\uff0c\u5e76\u5982\u5b9e\u58f0\u660e\u3002\u8bbe\u8ba1\u5df2\u5185\u7f6e\u5c0f\u6a21\u578b\u901a\u9053\u7f13\u89e3\u8be5\u98ce\u9669\u3002\n- **\u65f6\u95f4\u4f30\u7b97\uff08\u7c97\u7565\u3001\u3010\u5047\u8bbe\u3011\uff09**\uff1aGPTQ 7B \u91cf\u5316\u7ea6 0.5\u20131.5 h/\u683c\uff0c\u516d\u4efb\u52a1\u8bc4\u6d4b\u6570\u767e\u6761\u6837\u672c\u7ea6 0.5\u20132 h/\u683c\uff0cPPL \u5206\u949f\u7ea7\uff1bTinyLlama \u5404\u683c\u5206\u949f\u7ea7\u3002\u4e3b\u77e9\u9635\uff082 \u4e3b\u6a21\u578b\u00d78 \u683c\u00d73 seeds + 13B \u540c\u7ec4\uff09\u7ea6\u9700\u6570\u65e5\uff08GPU\uff09\u3002\n- **\u98ce\u9669\u4e0e\u7f13\u89e3**\uff1a\u2460 2 bit \u53ef\u80fd\u6570\u503c\u4e0d\u7a33\u5b9a/\u53d1\u6563\uff08NaN/Inf\uff09\u2192 \u6807\u8bb0\u4e3a\"\u4e0d\u7a33\u5b9a\u683c\"\u800c\u975e\u9759\u9ed8\u5220\u9664\uff0c\u7528 zero-point+clamp \u7f13\u89e3\uff1b\u2461 online RMSNorm \u6570\u503c\u6f02\u79fb \u2192 FP32 \u7d2f\u52a0 + C0 \u51fd\u6570\u7b49\u4ef7\u6821\u9a8c\u628a\u5173\uff0c\u5bb9\u5dee\u5185\u89c6\u4e3a\u901a\u8fc7\uff1b\u2462 \u65e0 GPU/\u6743\u91cd\u4e0b\u8f7d\u53d7\u9650 \u2192 \u9000\u5316\u4e3a\u5c0f\u6a21\u578b+PPL \u5e76\u58f0\u660e\uff1b\u2463 \u5b9e\u73b0\u504f\u79bb\u5b98\u65b9 \u2192 \u9010\u5c42\u5bf9\u7167 + \u65e5\u5fd7\u8bb0\u5f55\u4fdd\u771f\u5ea6\u504f\u5dee\u3002\n- **\u4ea4\u4ed8\u7269**\uff1a\u5b8c\u6574\u77e9\u9635\u7684 mean\u00b1std \u8868\u683c\u3001\u0394 \u6307\u6807\u8d8b\u52bf\u56fe\u3001PPL/\u4e0b\u6e38/\u8d44\u6e90\u4e09\u7ec4\u6307\u6807\u3001\u5b9e\u73b0\u4e0e\u590d\u73b0\u914d\u7f6e\u6e05\u5355\uff08\u542b\u5168\u90e8\u3010\u5047\u8bbe\u3011\u9ed8\u8ba4\u503c\u6e05\u5355\uff0c\u4fbf\u4e8e\u6309\u9700\u66ff\u6362\uff09\u3002\n\n## 8. \u5173\u952e\u3010\u5047\u8bbe\u3011\u6e05\u5355\u6c47\u603b\ng=128\uff08\u626b\u63cf 64/256\uff09\uff1bGPTQ \u6821\u51c6 128 \u6761\u00d7seq2048\uff1bdesc_act \u9ed8\u8ba4 True\uff08\u53e6\u505a\u654f\u611f\u6027\uff09\uff1bPPL stride 512/seq 2048\uff1bC4 \u56fa\u5b9a\u53ef\u590d\u73b0\u5b50\u96c6\uff1b3 seeds \u4e14 \u03b1=0.05\uff1b\u5206\u5757 Hadamard 256/\u5168\u7ef4\u5ea6\uff1bA100(80G)/H100 \u7b97\u529b\u524d\u63d0\uff1b\u5916\u90e8\u4f9d\u8d56\uff08\u5b98\u65b9\u4ed3\u5e93/\u9884\u8bad\u7ec3\u6743\u91cd\uff09\u53ef\u83b7\u53d6\uff1b\u4e0b\u6e38\u516d\u4efb\u52a1\u6e05\u5355\uff1bRTN \u4e0e GPTQ \u7edf\u4e00\u975e\u5bf9\u79f0\u9010\u7ec4\u91cf\u5316\u3002", "evidence": "\u63a2\u7d22\u5b9e\u6d4b\uff1a(1) /workspace \u4ec5\u542b task.json\uff08\u5185\u5bb9\u6ce8\u660e\u8bbe\u8ba1\u578b\u4efb\u52a1\uff09\uff1b(2) find \u5168\u76d8\u672a\u53d1\u73b0 track.md\u3001\u4efb\u4f55 QuaRot/GPTQ/RTN/Hadamard \u4ee3\u7801\u3001\u914d\u7f6e\u3001\u6587\u732e\u7b14\u8bb0\u6216\u6570\u636e\u96c6\uff1b/tmp\u3001/home/actor \u4e3a\u7a7a\uff1b(3) import torch/transformers/datasets/numpy \u5168\u90e8 ImportError\uff0cML \u4f9d\u8d56\u672a\u9884\u88c5\uff1b(4) nvidia-smi \u62a5\u544a\u65e0\u6cd5\u8fde\u63a5 GPU \u9a71\u52a8\uff0c\u65e0 GPU\uff0c224 \u6838 CPU\uff1b(5) \u6279\u51c6\u6d88\u606f\u660e\u786e\u4e86\u56db\u70b9\u9ed8\u8ba4\uff08\u8ba1\u7b97\u4fdd\u6301\u89e3\u8bfb\u3001\u9010\u5c42\u79bb\u7ebf PTQ\u30012\u00d72\u00d7{2,3,4}bit \u4e3b\u77e9\u9635\u4e0e g=128\u3001A100 \u7b97\u529b\u524d\u63d0+\u5c0f\u6a21\u578b\u901a\u9053\uff09\u53ca\"\u672a\u7ed9\u5b9a\u53d6\u503c\u4e00\u5f8b\u6807\u3010\u5047\u8bbe\u3011\"\u3002\u65b9\u6848\u57fa\u4e8e QuaRot(NeurIPS'24, Ashkboos et al.) \u4e0e GPTQ \u7684\u516c\u8ba4\u673a\u5236\u4f5c\u8bbe\u8ba1\u63a8\u65ad\uff0c\u672a\u6267\u884c\u4efb\u4f55\u8ba1\u7b97\u3002", "assumptions": ["\u4efb\u52a1\u6027\u8d28\uff1a\u7eaf\u8bbe\u8ba1\u4efb\u52a1\uff0c\u4e0d\u8981\u6c42\u4e5f\u4e0d\u8fd0\u884c\u5b9e\u9645\u5b9e\u9a8c\uff1b\u672c\u65b9\u6848\u4e0d\u58f0\u79f0\u4efb\u4f55\u5df2\u6d4b\u5f97\u7ed3\u679c\u3002", "\u56fa\u5b9a\u7ea6\u675f\uff08\u5df2\u7531\u9898\u76ee/\u7814\u7a76\u8005\u786e\u8ba4\uff09\uff1a\u4f4d\u5bbd 2/3/4 bit\uff1b\u4ec5\u91cf\u5316\u6743\u91cd\uff0c\u6fc0\u6d3b\u4e0e KV \u4fdd\u6301 FP16\uff1b\"weight-only+QuaRot\"\u6309\u8ba1\u7b97\u4fdd\u6301\u89e3\u8bfb\u4e3a\u4e3b\u8bbe\u8ba1\uff1b\u9010\u5c42/\u9010\u5757\u79bb\u7ebf post-training \u91cf\u5316\u3002", "\u672a\u7ed9\u5b9a\u53d6\u503c\u9ed8\u8ba4\uff1ag=128\uff08\u626b\u63cf 64/256\uff09\uff1bGPTQ \u6821\u51c6 128 \u6761\u00d7seq2048\uff1bdesc_act \u9ed8\u8ba4 True\uff08\u53e6\u505a\u654f\u611f\u6027\u68c0\u67e5\uff09\uff1bPPL stride 512\u3001seq 2048\uff1bC4 \u56fa\u5b9a\u53ef\u590d\u73b0\u5b50\u96c6\uff1b\u6bcf\u683c 3 seeds\u3001\u03b1=0.05\uff1b\u5206\u5757 Hadamard \u5757\u5927\u5c0f 256 \u6216\u5168\u7ef4\u5ea6\u3002", "\u5b9e\u73b0\u84dd\u672c\u4e3a QuaRot \u5b98\u65b9\u4ed3\u5e93\u4e0e AutoGPTQ/GPTQ-for-LLaMA\uff0c\u9884\u8bad\u7ec3\u6743\u91cd HF \u53ef\u4e0b\u8f7d\uff1b\u8fd9\u4e9b\u4e3a\u5916\u90e8\u5f85\u83b7\u53d6\u4f9d\u8d56\uff08\u672c\u73af\u5883\u65e0\u7f51\u7edc\uff09\u3002", "\u7b97\u529b\u524d\u63d0\u4e3a \u22651\u00d7A100(80G)/H100\uff1b\u65e0\u5219\u4ec5\u5c0f\u6a21\u578b+PPL \u53ef\u6267\u884c\u5e76\u5982\u5b9e\u58f0\u660e\uff08\u65b9\u6848\u5185\u7f6e\u5c0f\u6a21\u578b\u901a\u9053\uff09\u3002", "RTN \u4e0e GPTQ \u7edf\u4e00\u9010\u7ec4\u975e\u5bf9\u79f0\uff08zero-point\uff09\u91cf\u5316\u53c2\u6570\u5316\uff0c\u4ec5\u5dee\u5728\u662f\u5426\u7528 Hessian \u6821\u6b63\u3002"], "uncertainties": ["\u65cb\u8f6c\u63d2\u5165/\u878d\u5408\u7684\u786e\u5207\u9010\u5c42\u5b9e\u73b0\u7ec6\u8282\uff08\u662f\u5426\u542b V \u65cb\u8f6c\u3001\u5757\u95f4 online LN \u7684\u7ec4\u5408\u65b9\u5f0f\uff09\u9700\u5bf9\u7167\u5b98\u65b9 QuaRot \u4ed3\u5e93\u786e\u8ba4\uff0c\u672c\u65b9\u6848\u6309\u6587\u732e\u516c\u8ba4\u673a\u5236\u63cf\u8ff0\u3002", "2 bit \u4e0b\u90e8\u5206\u683c\u53ef\u80fd\u51fa\u73b0\u6570\u503c\u4e0d\u7a33\u5b9a\uff08NaN/Inf\uff09\uff0c\u5c06\u6807\u4e3a\u4e0d\u7a33\u5b9a\u683c\u800c\u975e\u7701\u7565\u3002", "\u5b9e\u9645\u4e0b\u6e38\u4efb\u52a1\u8bc4\u6d4b\u7ed3\u679c\u4e0e\u5df2\u53d1\u8868\u5bf9\u7167\u6570\u5b57\u7684\u504f\u5dee\u65b9\u5411\u672a\u77e5\uff08\u672a\u8fd0\u884c\uff09\u3002", "\u82e5\u5916\u90e8\u4f9d\u8d56/\u6743\u91cd\u65e0\u6cd5\u83b7\u53d6\uff0c\u5219\u9000\u5316\u4e3a\u5c0f\u6a21\u578b+PPL \u5b50\u96c6\uff0c\u6700\u7ec8\u53ef\u884c\u8303\u56f4\u4ee5\u